#!/usr/bin/env bash
# SessionStart: security-threat-model-canon-citation's directive — the canon-references record field discipline.
. "${CLAUDE_PLUGIN_ROOT_CORE:-$(cd "$(dirname "${BASH_SOURCE[0]}")/../../core" && pwd -P)}/hooks/lib/role-directive.sh"
core_role_directive $'YOU DECIDE: no-copy canon citation discipline for the canon-references record field' $'USE WHEN: the canon-references field in this role\'s phase-2 record (and any reference to external canon inside a phase-1 proposal) must cite external canon by path/description only — never by pasting its content. "External canon" means core\'s warrant/ plugin, any sibling methodology plugin\'s hooks/methodology-gate.sh (or other hook script), and any other canon document or script that lives outside the file you are currently writing' $'PRODUCES: a citation as a relative path (e.g. core/warrant/hooks/...), plus a short description of what it establishes and why it is relevant here. Do not paste the script\'s content, its shebang line, or excerpts long enough to functionally reconstruct it' $'HAND-OFF: this applies to the canon-references field specifically. It does not relax or replace any other field\'s own discipline (STRIDE ordering, rating markers, disposition vocabulary, sign-off references) — those are owned by the other methodology plugins in this set.\nA mechanical backstop (hooks/methodology-gate.sh) checks this on write, but it is a best-effort heuristic, not a substitute for review.'
